/*
 * A182670  Floor-sum sequence of r, where r = golden ratio = (1+sqrt(5))/2
 *          and a(1)=2, a(2)=3.
 * https://oeis.org/A182670
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 14, u32 n <= 3000, u64 n <= 3000,
 *            u128 n <= 3000, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* OEIS A182670 (Floor‑sum sequence of the golden ratio). */
/* The sequence is generated by the minimally closed set under
   floor((m+n)*φ) with seeds 2 and 3, where φ = (1+√5)/2. */

#include <stdlib.h>
#include "../utils/floor_sqrt.h"

typedef struct {
    seq_t val;        /* floor((S[i]+S[j])*φ) value          */
    idx_t i;          /* smaller index in S (i < j)          */
    idx_t j;          /* larger index in S                   */
} Candidate;

/* ---------- dynamic array for the sequence S ----------------- */
static seq_t *S = NULL;
static size_t S_cap = 0;     /* capacity of S, not size */
static size_t S_size = 0;    /* current size of S */

/* ---------- min‑heap for candidates --------------------------- */
static Candidate *heap = NULL;
static size_t heap_cap = 0;
static size_t heap_size = 0;

/* ---------- helper: exact floor of k*φ ------------------------ */
static inline seq_t val_of_pair(idx_t i, idx_t j)
{
    seq_t k = S[i] + S[j];
    seq_t sq = k * k;          /* k²  */
    sq *= 5;                   /* 5·k² */
    seq_t root = floor_sqrt(sq);/* floor(√(5k²)) = floor(k√5) */
    return (k + root) / 2;     /* floor(kφ) = (k + floor(k√5))/2   */
}

/* ---------- heap operations ----------------------------------- */
static void heap_push(Candidate c)
{
    if (heap_size == heap_cap) {
        heap_cap = (heap_cap == 0) ? 4 : heap_cap * 2;
        heap = (Candidate *)realloc(heap, heap_cap * sizeof(Candidate));
    }
    size_t pos = heap_size++;
    while (pos > 0) {
        size_t parent = (pos - 1) >> 1;
        if (heap[parent].val <= c.val) break;
        heap[pos] = heap[parent];
        pos = parent;
    }
    heap[pos] = c;
}

static Candidate heap_pop(void)
{
    Candidate top = heap[0];
    heap_size--;
    Candidate last = heap[heap_size];
    size_t pos = 0;
    while (1) {
        size_t left = (pos << 1) + 1;
        if (left >= heap_size) break;
        size_t right = left + 1;
        size_t child = (right < heap_size && heap[right].val < heap[left].val)
                       ? right : left;
        if (heap[child].val >= last.val) break;
        heap[pos] = heap[child];
        pos = child;
    }
    heap[pos] = last;
    return top;
}

/* ---------- ensure capacity ----------------------------------- */
static void ensure_S_capacity(size_t needed)
{
    if (S_cap < needed) {
        S_cap = (needed > S_cap * 2) ? needed : S_cap * 2;
        S = (seq_t *)realloc(S, S_cap * sizeof(seq_t));
    }
}

/* ---------- add a new element to the sequence ----------------- */
static void append_value(seq_t value)
{
    ensure_S_capacity(S_size + 1);
    S[S_size++] = value;
    /* after adding a new element with index j = S_size-1, push
       its first candidate (i=0) to the heap                       */
    idx_t j = S_size - 1;
    if (j > 0) {                       /* only if there is a smaller element */
        Candidate c;
        c.i = 0;
        c.j = j;
        c.val = val_of_pair(c.i, c.j);
        heap_push(c);
    }
}

/* ---------- the required function ----------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0; /* undefined for the problem, just guard        */

    /* lazy initialization of the seeds */
    if (S_size == 0) {
        /* add first seed 2 */
        append_value((seq_t)2);
        /* add second seed 3 */
        append_value((seq_t)3);
        /* push the first candidate (2,3) -> 8 */
        Candidate init;
        init.i = 0;
        init.j = 1;                       /* j = index of 3       */
        init.val = val_of_pair(init.i, init.j);
        heap_push(init);
    }

    /* generate terms until we have at least n of them */
    while (S_size < n) {
        Candidate c = heap_pop();
        /* check for duplicate: if value equals last term,
           we skip adding it, otherwise we append it        */
        if (c.val != S[S_size - 1]) {
            append_value(c.val);
        }
        /* push next candidate for this pair (i+1, j) if legal   */
        idx_t next_i = c.i + 1;
        if (next_i < c.j) {
            Candidate nxt;
            nxt.i = next_i;
            nxt.j = c.j;
            nxt.val = val_of_pair(nxt.i, nxt.j);
            heap_push(nxt);
        }
    }
    return S[n - 1];
}
